# ============================================================================\n# Setup & Verification Script for CASME II Training Pipeline\n# ============================================================================\n\nimport os\nimport sys\nfrom pathlib import Path\nimport subprocess\n\n\ndef print_header(text):\n    \"\"\"Print formatted header\"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(f\"  {text}\")\n    print(\"=\"*60 + \"\\n\")\n\n\ndef print_status(message, status=\"✓\"):\n    \"\"\"Print status message\"\"\"\n    print(f\"  [{status}] {message}\")\n\n\ndef check_python():\n    \"\"\"Check Python version\"\"\"\n    print_header(\"Checking Python Version\")\n    version = f\"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}\"\n    if sys.version_info >= (3, 8):\n        print_status(f\"Python {version} - OK\")\n        return True\n    else:\n        print_status(f\"Python {version} - FAILED (requires 3.8+)\", \"✗\")\n        return False\n\n\ndef check_dependencies():\n    \"\"\"Check if required packages are installed\"\"\"\n    print_header(\"Checking Dependencies\")\n    \n    required = [\n        'torch',\n        'torchvision',\n        'cv2',\n        'pandas',\n        'numpy',\n        'sklearn',\n        'tensorboard',\n    ]\n    \n    missing = []\n    for package in required:\n        try:\n            __import__(package)\n            print_status(f\"{package}\")\n        except ImportError:\n            print_status(f\"{package} - MISSING\", \"✗\")\n            missing.append(package)\n    \n    if missing:\n        print(f\"\\n  ⚠️  Missing packages: {', '.join(missing)}\")\n        print(f\"\\n  Install with: pip install -r requirements.txt\\n\")\n        return False\n    return True\n\n\ndef check_gpu():\n    \"\"\"Check CUDA availability\"\"\"\n    print_header(\"Checking GPU\")\n    \n    try:\n        import torch\n        if torch.cuda.is_available():\n            print_status(f\"CUDA available: {torch.cuda.get_device_name(0)}\")\n            print_status(f\"CUDA Version: {torch.version.cuda}\")\n            print_status(f\"PyTorch Version: {torch.__version__}\")\n            return True\n        else:\n            print_status(\"No CUDA device found - will use CPU\", \"⚠️ \")\n            print_status(\"(Training will be slower on CPU)\")\n            return False\n    except Exception as e:\n        print_status(f\"Error checking GPU: {e}\", \"✗\")\n        return False\n\n\ndef check_data():\n    \"\"\"Check dataset structure\"\"\"\n    print_header(\"Checking Dataset Structure\")\n    \n    checks = [\n        (\"Cropped/Cropped\", \"Cropped face sequences\"),\n        (\"CASME2-coding-20140508.xlsx\", \"Labels file\"),\n    ]\n    \n    all_ok = True\n    for path, description in checks:\n        full_path = Path(path)\n        if full_path.exists():\n            if full_path.is_dir():\n                count = len(list(full_path.glob(\"*\")))\n                print_status(f\"{description}: {path} ({count} items)\")\n            else:\n                size_mb = full_path.stat().st_size / (1024**2)\n                print_status(f\"{description}: {path} ({size_mb:.1f}MB)\")\n        else:\n            print_status(f\"{description}: {path} - NOT FOUND\", \"✗\")\n            all_ok = False\n    \n    return all_ok\n\n\ndef check_config():\n    \"\"\"Check configuration files\"\"\"\n    print_header(\"Checking Configuration Files\")\n    \n    config_files = [\n        'config.py',\n        'dataset.py',\n        'preprocessing.py',\n        'models.py',\n        'train.py',\n        'inference.py',\n        'wellness_score.py',\n    ]\n    \n    all_ok = True\n    for file in config_files:\n        if Path(file).exists():\n            print_status(f\"{file}\")\n        else:\n            print_status(f\"{file} - NOT FOUND\", \"✗\")\n            all_ok = False\n    \n    return all_ok\n\n\ndef check_directories():\n    \"\"\"Create necessary directories\"\"\"\n    print_header(\"Creating Output Directories\")\n    \n    dirs = [\n        'checkpoints',\n        'logs',\n    ]\n    \n    for dir_name in dirs:\n        Path(dir_name).mkdir(exist_ok=True)\n        print_status(f\"Directory: {dir_name}\")\n\n\ndef verify_model():\n    \"\"\"Verify model can be instantiated\"\"\"\n    print_header(\"Verifying Model Architecture\")\n    \n    try:\n        import torch\n        from models import build_model\n        from config import Config\n        \n        device = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n        \n        # Test model instantiation\n        model = build_model(\n            model_type=Config.MODEL_TYPE,\n            num_classes=Config.NUM_CLASSES,\n            temporal_length=Config.TEMPORAL_LENGTH,\n            input_channels=Config.MODEL_INPUT_CHANNELS,\n            device=device,\n        )\n        \n        # Test forward pass\n        dummy_input = torch.randn(2, 12, 7, 224, 224).to(device)\n        output = model(dummy_input)\n        \n        total_params = sum(p.numel() for p in model.parameters())\n        trainable = sum(p.numel() for p in model.parameters() if p.requires_grad)\n        \n        print_status(f"Model type: {Config.MODEL_TYPE}")\n        print_status(f\"Total parameters: {total_params:,}\")\n        print_status(f\"Trainable parameters: {trainable:,}\")\n        print_status(f"Input shape: (2, {Config.TEMPORAL_LENGTH}, {Config.MODEL_INPUT_CHANNELS}, 224, 224)")\n        print_status(f\"Output shape: {output.shape}\")\n        \n        return True\n    except Exception as e:\n        print_status(f\"Model verification failed: {e}\", \"✗\")\n        import traceback\n        traceback.print_exc()\n        return False\n\n\ndef test_dataset():\n    \"\"\"Test dataset loading\"\"\"\n    print_header(\"Testing Dataset Loading\")\n    \n    try:\n        from dataset import create_dataloaders\n        from config import Config\n        \n        print_status(\"Loading dataloaders...\")\n        train_loader, val_loader, test_loader = create_dataloaders(\n            root_dir=Config.CROPPED_DATA_PATH,\n            labels_file=Config.LABELS_FILE,\n            batch_size=2,\n            num_workers=0,  # Use 0 for testing\n        )\n        \n        print_status(f\"Train samples: {len(train_loader.dataset)}\")\n        print_status(f\"Val samples: {len(val_loader.dataset)}\")\n        print_status(f\"Test samples: {len(test_loader.dataset)}\")\n        \n        # Test batch loading\n        print_status(\"Loading sample batch...\")\n        frames, labels = next(iter(train_loader))\n        print_status(f\"Batch shape: {frames.shape}\")\n        print_status(f\"Labels shape: {labels.shape}\")\n        \n        return True\n    except Exception as e:\n        print_status(f\"Dataset test failed: {e}\", \"✗\")\n        import traceback\n        traceback.print_exc()\n        return False\n\n\ndef show_quick_start():\n    \"\"\"Show quick start commands\"\"\"\n    print_header(\"Quick Start Commands\")\n    \n    commands = [\n        (\"Train model\", \"python train.py\"),\n        (\"Monitor training\", \"tensorboard --logdir=logs\"),\n        (\"Run inference\", \"python inference.py\"),\n        (\"Test dataset\", \"python dataset.py\"),\n        (\"Test models\", \"python models.py\"),\n    ]\n    \n    print(\"\\n  Run any of these commands:\\n\")\n    for desc, cmd in commands:\n        print(f\"    {desc}:\")\n        print(f\"      $ {cmd}\\n\")\n\n\ndef main():\n    \"\"\"Run all verification checks\"\"\"\n    print(\"\\n\")\n    print(\"╔\" + \"=\"*58 + \"╗\")\n    print(\"║\" + \" \"*58 + \"║\")\n    print(\"║\" + \"  CASME II Micro-Expression Classification Setup\".center(58) + \"║\")\n    print(\"║\" + \"  Panjaayathu Engine v1.0\".center(58) + \"║\")\n    print(\"║\" + \" \"*58 + \"║\")\n    print(\"╚\" + \"=\"*58 + \"╝\\n\")\n    \n    checks = [\n        (\"Python Version\", check_python),\n        (\"Dependencies\", check_dependencies),\n        (\"GPU\", check_gpu),\n        (\"Configuration Files\", check_config),\n        (\"Dataset\", check_data),\n        (\"Output Directories\", check_directories),\n        (\"Model Architecture\", verify_model),\n        (\"Dataset Loading\", test_dataset),\n    ]\n    \n    results = {}\n    for name, check_fn in checks:\n        try:\n            results[name] = check_fn()\n        except Exception as e:\n            print_status(f\"Unexpected error: {e}\", \"✗\")\n            results[name] = False\n    \n    # Summary\n    print_header(\"Summary\")\n    \n    passed = sum(1 for v in results.values() if v)\n    total = len(results)\n    \n    for name, result in results.items():\n        status = \"✓\" if result else \"✗\"\n        print_status(f\"{name}\", status)\n    \n    print(f\"\\n  Total: {passed}/{total} checks passed\\n\")\n    \n    if passed == total:\n        print(\"  🎉 All checks passed! You're ready to train!\\n\")\n        show_quick_start()\n        return 0\n    else:\n        print(\"  ⚠️  Some checks failed. Please fix issues above.\\n\")\n        return 1\n\n\nif __name__ == \"__main__\":\n    exit(main())\n